<?php
if (!defined('ABSPATH')) { exit; }
/** Remboursements partiels et complets des ventes. */
final class FKC_Refunds_API {
 private static function t($n){global $wpdb;return in_array($n,array('users','tenants','branches','members','permissions','branch_access','invitations','audit_logs','sessions'),true)?'bta_'.$n:$wpdb->prefix.'bta_'.$n;}
 private static function err($c,$m,$s=400){return new WP_Error($c,$m,array('status'=>$s));}
 private static function auth($r,$tenant){$h=$r->get_header('authorization');if(!$h&&isset($_SERVER['HTTP_AUTHORIZATION']))$h=wp_unslash($_SERVER['HTTP_AUTHORIZATION']);if(!is_string($h)||!preg_match('/^Bearer\s+([a-fA-F0-9]{64})$/',$h,$m))return self::err('bta_unauthenticated','Connexion requise.',401);global $wpdb;$s=$wpdb->get_row($wpdb->prepare('SELECT s.user_id,u.status FROM '.self::t('sessions').' s JOIN '.self::t('users').' u ON u.id=s.user_id WHERE s.token_hash=%s AND s.expires_at>%s LIMIT 1',hash('sha256',$m[1]),gmdate('Y-m-d H:i:s')),ARRAY_A);if(!$s||$s['status']!=='ACTIVE')return self::err('bta_unauthenticated','Session invalide ou expirée.',401);$mem=$wpdb->get_row($wpdb->prepare("SELECT role FROM ".self::t('members')." WHERE tenant_id=%d AND user_id=%d AND status='ACTIVE' LIMIT 1",$tenant,$s['user_id']),ARRAY_A);$roles=array('OWNER','ADMIN','MANAGER');if(!$mem||!in_array($mem['role'],$roles,true))return self::err('bta_forbidden','Permission sales.cancel requise.',403);return array('user_id'=>(int)$s['user_id']);}
 public static function boot(){add_action('rest_api_init',array(__CLASS__,'routes'));}
 public static function routes(){register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/sales/(?P<sale_id>\d+)/refunds',array(array('methods'=>'GET','callback'=>array(__CLASS__,'list_refunds'),'permission_callback'=>'__return_true'),array('methods'=>'POST','callback'=>array(__CLASS__,'create_refund'),'permission_callback'=>'__return_true')));}
 public static function list_refunds($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t);if(is_wp_error($a))return $a;global $wpdb;$id=(int)$r['sale_id'];if(!$wpdb->get_var($wpdb->prepare('SELECT id FROM '.self::t('sales').' WHERE id=%d AND tenant_id=%d',$id,$t)))return self::err('bta_sale_not_found','Vente introuvable.',404);$rows=$wpdb->get_results($wpdb->prepare('SELECT id,amount,currency,method,reference,notes,created_by,created_at FROM '.self::t('sale_refunds').' WHERE tenant_id=%d AND sale_id=%d ORDER BY id DESC',$t,$id),ARRAY_A);return array('success'=>true,'refunds'=>$rows);}
 public static function create_refund($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t);if(is_wp_error($a))return $a;$id=(int)$r['sale_id'];$amount=$r->get_param('amount');$method=strtoupper(sanitize_key((string)($r->get_param('method')?:'CASH')));if(!is_numeric($amount)||(float)$amount<=0||!in_array($method,array('CASH','MOBILE_MONEY','BANK','OTHER'),true))return self::err('bta_invalid_refund','Montant ou mode de remboursement invalide.');global $wpdb;$wpdb->query('START TRANSACTION');$sale=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::t('sales')." WHERE id=%d AND tenant_id=%d FOR UPDATE",$id,$t),ARRAY_A);if(!$sale||$sale['status']!=='COMPLETED'){$wpdb->query('ROLLBACK');return self::err('bta_sale_not_refundable','Vente introuvable ou non remboursable.',409);}$already=(float)$wpdb->get_var($wpdb->prepare('SELECT COALESCE(SUM(amount),0) FROM '.self::t('sale_refunds').' WHERE tenant_id=%d AND sale_id=%d',$t,$id));$remaining=(float)$sale['paid']-$already;$amount=(float)$amount;if($amount>$remaining+0.00001){$wpdb->query('ROLLBACK');return self::err('bta_refund_exceeds_paid','Le remboursement dépasse le montant encaissé restant.',409);} $now=gmdate('Y-m-d H:i:s');$ok=$wpdb->insert(self::t('sale_refunds'),array('tenant_id'=>$t,'branch_id'=>$sale['branch_id'],'sale_id'=>$id,'amount'=>$amount,'currency'=>$sale['currency'],'method'=>$method,'reference'=>sanitize_text_field((string)$r->get_param('reference')),'notes'=>sanitize_textarea_field((string)$r->get_param('notes')),'created_by'=>$a['user_id'],'created_at'=>$now));if(!$ok){$wpdb->query('ROLLBACK');return self::err('bta_refund_failed','Remboursement non enregistré.',500);}$refund_id=(int)$wpdb->insert_id;$ok=$wpdb->insert(self::t('payments'),array('tenant_id'=>$t,'branch_id'=>$sale['branch_id'],'entity_type'=>'SALE','entity_id'=>$id,'payment_type'=>'SALE_REFUND','amount'=>$amount,'currency'=>$sale['currency'],'exchange_rate'=>$sale['exchange_rate'],'method'=>$method,'reference'=>sanitize_text_field((string)$r->get_param('reference')),'notes'=>'Remboursement vente '.$sale['reference'],'created_by'=>$a['user_id'],'created_at'=>$now));if(!$ok){$wpdb->query('ROLLBACK');return self::err('bta_refund_payment_failed','Écriture financière impossible.',500);}if($method==='CASH'){$cash=$wpdb->get_row($wpdb->prepare("SELECT id FROM ".self::t('cash_sessions')." WHERE tenant_id=%d AND branch_id=%d AND user_id=%d AND currency=%s AND status='OPEN' ORDER BY id DESC LIMIT 1 FOR UPDATE",$t,$sale['branch_id'],$a['user_id'],$sale['currency']),ARRAY_A);if(!$cash){$wpdb->query('ROLLBACK');return self::err('bta_open_cash_required','Ouvre une caisse dans la devise de la vente avant le remboursement en espèces.',409);}$ok=$wpdb->insert(self::t('cash_movements'),array('tenant_id'=>$t,'cash_session_id'=>$cash['id'],'movement_type'=>'CASH_OUT','amount'=>$amount,'currency'=>$sale['currency'],'description'=>'Remboursement vente '.$sale['reference'],'reference_type'=>'sale_refund','reference_id'=>$refund_id,'created_by'=>$a['user_id'],'created_at'=>$now));if(!$ok){$wpdb->query('ROLLBACK');return self::err('bta_cash_refund_failed','Sortie de caisse impossible.',500);}}$wpdb->query('COMMIT');return new WP_REST_Response(array('success'=>true,'refund_id'=>$refund_id,'sale_id'=>$id,'refunded_total'=>$already+$amount,'remaining_refundable'=>(float)$sale['paid']-$already-$amount,'currency'=>$sale['currency'],'cash_recorded'=>$method==='CASH'),201);}
}
